export const red = {
  gatewayEndpoint: { id: "gateway-endpoint-s3", servicio: "s3" },
  tablas: [
    {
      id: "rtb-app-a",
      subredes: ["subnet-app-a"],
      rutas: [
        { destino: "10.0.0.0/16", objetivo: "local" },
        { destino: "0.0.0.0/0", objetivo: "nat-gateway-1" },
        { destino: "pl-s3", objetivo: "gateway-endpoint-s3" },
      ],
    },
    {
      id: "rtb-app-b",
      subredes: ["subnet-app-b"],
      rutas: [
        { destino: "10.0.0.0/16", objetivo: "local" },
        { destino: "0.0.0.0/0", objetivo: "nat-gateway-2" },
        { destino: "pl-s3", objetivo: "gateway-endpoint-s3" },
      ],
    },
  ],
};

spec.code:
const tabla = red.tablas.find((t) => t.id === "rtb-app-b");
assert.ok(tabla, "debe existir la tabla rtb-app-b");
assert.ok(tabla.rutas.some((r) => r.destino === "pl-s3" && r.objetivo === red.gatewayEndpoint.id), "falta la ruta del endpoint en rtb-app-b");

for (const tabla of red.tablas) {
  const rutasS3 = tabla.rutas.filter((r) => r.destino === "pl-s3");
  assert.strictEqual(rutasS3.length, 1, tabla.id + " debe tener una sola ruta de endpoint a S3");
}

const a = red.tablas.find((t) => t.id === "rtb-app-a");
const b = red.tablas.find((t) => t.id === "rtb-app-b");
assert.ok(a.rutas.some((r) => r.destino === "10.0.0.0/16" && r.objetivo === "local"));
assert.ok(a.rutas.some((r) => r.destino === "0.0.0.0/0" && r.objetivo === "nat-gateway-1"));
assert.ok(b.rutas.some((r) => r.destino === "10.0.0.0/16" && r.objetivo === "local"));
assert.ok(b.rutas.some((r) => r.destino === "0.0.0.0/0" && r.objetivo === "nat-gateway-2"));

