export const config = {
  vpc: { id: "vpc-app", enableDnsSupport: true, enableDnsHostnames: true },
  endpoint: {
    tipo: "Interface",
    servicio: "servicio-de-aws-con-privatelink",
    privateDnsEnabled: true,
    subredes: [
      { id: "subnet-a", zona: "zona-a" },
      { id: "subnet-b", zona: "zona-b" },
    ],
    securityGroup: { entrada: [{ protocolo: "tcp", puerto: 443, origen: "10.0.0.0/16" }] },
  },
};

spec.code:
assert.deepStrictEqual(config.endpoint.subredes, [
  { id: "subnet-a", zona: "zona-a" },
  { id: "subnet-b", zona: "zona-b" },
]);
assert.deepStrictEqual(config.endpoint.securityGroup.entrada, [{ protocolo: "tcp", puerto: 443, origen: "10.0.0.0/16" }]);
